<main class="py-5"><div class="container"><h1 class="h2 text-primary mb-4">Gestion des menus</h1>
<section class="card border-0 shadow-sm mb-4"><div class="card-body"><h2 class="h5">Créer un menu</h2><form method="post" action="/admin/menus" class="row g-3"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><div class="col-md-6"><label class="form-label">Titre</label><input class="form-control" name="title" required></div><div class="col-md-6"><label class="form-label">Thème</label><input class="form-control" name="theme" required></div><div class="col-md-6"><label class="form-label">Régime</label><select class="form-select" name="dietary_regime"><option value="classic">Classique</option><option value="vegetarian">Végétarien</option><option value="vegan">Végan</option><option value="other">Autre</option></select></div><div class="col-md-3"><label class="form-label">Minimum personnes</label><input class="form-control" type="number" min="1" name="min_people" required></div><div class="col-md-3"><label class="form-label">Prix du menu (minimum de personnes)</label><input class="form-control" type="number" step="0.01" min="0" name="base_price" required></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" required></textarea></div><div class="col-12"><label class="form-label">Conditions</label><textarea class="form-control" name="conditions" required></textarea></div><div class="col-md-3"><label class="form-label">Stock</label><input class="form-control" type="number" min="0" name="available_stock" required></div><div class="col-12"><button class="btn btn-primary">Créer</button></div></form></div></section>
<?php foreach($menus as $menu): ?><section class="card border-0 shadow-sm mb-3"><div class="card-body"><h2 class="h5"><?= $escape($menu->getTitle()) ?></h2><form method="post" action="/admin/menus/<?= $menu->getId() ?>" class="row g-3"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="_method" value="PUT"><div class="col-md-6"><label class="form-label">Titre</label><input class="form-control" name="title" value="<?= $escape($menu->getTitle()) ?>" required></div><div class="col-md-6"><label class="form-label">Thème</label><input class="form-control" name="theme" value="<?= $escape($menu->getTheme()) ?>" required></div><div class="col-md-6"><label class="form-label">Régime</label><select class="form-select" name="dietary_regime"><?php foreach(['classic'=>'Classique','vegetarian'=>'Végétarien','vegan'=>'Végan','other'=>'Autre'] as $v=>$label): ?><option value="<?= $v ?>" <?= $menu->getDietaryRegime()===$v?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Minimum</label><input class="form-control" type="number" min="1" name="min_people" value="<?= $menu->getMinPeople() ?>" required></div><div class="col-md-3"><label class="form-label">Prix du menu (minimum de <?= $menu->getMinPeople() ?> personnes)</label><input class="form-control" type="number" step="0.01" name="base_price" value="<?= $menu->getBasePrice() ?>" required></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" required><?= $escape($menu->getDescription()) ?></textarea></div><div class="col-12"><label class="form-label">Conditions</label><textarea class="form-control" name="conditions" required><?= $escape($menu->getConditions()) ?></textarea></div><div class="col-md-3"><label class="form-label">Stock</label><input class="form-control" type="number" min="0" name="available_stock" value="<?= $menu->getAvailableStock() ?>" required></div><div class="col-12"><button class="btn btn-outline-primary me-2">Enregistrer</button></form><form method="post" action="/admin/menus/<?= $menu->getId() ?>/delete" class="d-inline"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><button class="btn btn-outline-danger btn-sm" data-confirm="Désactiver ce menu ?">Désactiver</button></form></div></div></section><?php endforeach; ?>
